/* ChartPulse — Dark Trading Terminal Theme */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --bg-primary: #131722;
  --bg-secondary: #1e222d;
  --bg-tertiary: #2a2e39;
  --bg-hover: #363a45;
  --accent: #2962FF;
  --accent-hover: #1e53e5;
  --positive: #26a69a;
  --positive-bg: rgba(38,166,154,0.12);
  --negative: #ef5350;
  --negative-bg: rgba(239,83,80,0.12);
  --text-primary: #d1d4dc;
  --text-secondary: #787b86;
  --text-muted: #4c525e;
  --border: #2a2e39;
  --border-light: #363a45;
  --white: #ffffff;
  --gold: #f0b90b;
  --gold-bg: rgba(240,185,11,0.1);
  --platinum: #e5e4e2;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --nav-height: 56px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: var(--accent); text-decoration: none; transition: color 0.15s; }
a:hover { color: var(--accent-hover); }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; }
input, select { font-family: inherit; }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--bg-tertiary); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--bg-hover); }

/* ===== NAVIGATION ===== */
.navbar {
  position: sticky; top: 0; z-index: 100;
  display: flex; align-items: center; justify-content: space-between;
  height: var(--nav-height);
  padding: 0 24px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(12px);
}
.nav-brand {
  display: flex; align-items: center; gap: 8px;
  font-size: 1.25rem; font-weight: 700; color: var(--white);
  text-decoration: none;
}
.nav-brand i { color: var(--accent); font-size: 1.5rem; }
.nav-links { display: flex; gap: 4px; }
.nav-links a {
  padding: 8px 16px; border-radius: var(--radius-md);
  color: var(--text-secondary); font-size: 0.875rem; font-weight: 500;
  transition: all 0.15s;
}
.nav-links a:hover { color: var(--text-primary); background: var(--bg-tertiary); }
.nav-links a.active { color: var(--accent); background: rgba(41,98,255,0.1); }
.nav-right { display: flex; align-items: center; gap: 12px; }
.nav-search {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 12px; background: var(--bg-tertiary); border-radius: var(--radius-md);
  color: var(--text-secondary); font-size: 0.8rem;
}
.nav-search i { font-size: 0.875rem; }
.btn-primary {
  padding: 8px 20px; background: var(--accent); color: var(--white);
  border: none; border-radius: var(--radius-md); font-weight: 600;
  font-size: 0.875rem; transition: background 0.15s;
}
.btn-primary:hover { background: var(--accent-hover); }
.btn-outline {
  padding: 8px 20px; background: transparent; color: var(--text-primary);
  border: 1px solid var(--border-light); border-radius: var(--radius-md);
  font-weight: 500; font-size: 0.875rem; transition: all 0.15s;
}
.btn-outline:hover { border-color: var(--text-secondary); }

/* ===== HERO ===== */
.hero {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; padding: 80px 24px 60px;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}
.hero h1 {
  font-size: 2.75rem; font-weight: 700; line-height: 1.2;
  max-width: 700px; margin-bottom: 16px; color: var(--white);
}
.hero h1 span { color: var(--accent); }
.hero p {
  font-size: 1.125rem; color: var(--text-secondary);
  max-width: 560px; margin-bottom: 32px; line-height: 1.6;
}
.hero-actions { display: flex; gap: 12px; }
.hero .btn-primary { padding: 12px 32px; font-size: 1rem; }
.hero .btn-outline { padding: 12px 32px; font-size: 1rem; }

/* ===== MARKET SUMMARY BAR ===== */
.market-summary {
  display: flex; gap: 0; padding: 0 24px;
  background: var(--bg-secondary); border-bottom: 1px solid var(--border);
  overflow-x: auto;
}
.market-summary-item {
  display: flex; flex-direction: column; padding: 12px 20px;
  border-right: 1px solid var(--border); min-width: 140px;
  white-space: nowrap;
}
.market-summary-item:last-child { border-right: none; }
.market-summary-item .label {
  font-size: 0.7rem; color: var(--text-secondary);
  text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 2px;
}
.market-summary-item .price {
  font-size: 0.95rem; font-weight: 600; color: var(--text-primary);
}
.market-summary-item .change { font-size: 0.75rem; font-weight: 500; }
.change.positive { color: var(--positive); }
.change.negative { color: var(--negative); }

/* ===== SECTION LAYOUT ===== */
.section {
  padding: 32px 24px;
  max-width: 1400px;
  margin: 0 auto;
}
.section-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 20px;
}
.section-title {
  font-size: 1.25rem; font-weight: 600; color: var(--white);
}

/* ===== TABS ===== */
.tabs {
  display: flex; gap: 2px; background: var(--bg-tertiary);
  border-radius: var(--radius-md); padding: 2px;
}
.tab-btn {
  padding: 6px 14px; border: none; background: transparent;
  color: var(--text-secondary); font-size: 0.8rem; font-weight: 500;
  border-radius: var(--radius-sm); transition: all 0.15s; white-space: nowrap;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active {
  background: var(--accent); color: var(--white);
}
.tabs-simple { display: flex; gap: 16px; }
.tabs-simple .tab-btn {
  padding: 4px 0; border: none; background: transparent;
  color: var(--text-secondary); font-size: 0.875rem; font-weight: 500;
  border-bottom: 2px solid transparent; border-radius: 0;
  transition: all 0.15s;
}
.tabs-simple .tab-btn:hover { color: var(--text-primary); }
.tabs-simple .tab-btn.active {
  color: var(--accent); border-bottom-color: var(--accent);
}

/* ===== TAB PANELS ===== */
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ===== DATA TABLES ===== */
.data-table {
  width: 100%; border-collapse: collapse; font-size: 0.85rem;
}
.data-table th {
  text-align: left; padding: 10px 12px; font-weight: 500;
  color: var(--text-secondary); border-bottom: 1px solid var(--border);
  font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.5px;
  position: sticky; top: 0; background: var(--bg-secondary);
}
.data-table td {
  padding: 10px 12px; border-bottom: 1px solid var(--border);
  vertical-align: middle;
}
.data-table tr:hover td { background: var(--bg-tertiary); }
.data-table .ticker {
  font-weight: 600; color: var(--text-primary);
}
.data-table .company { color: var(--text-secondary); font-size: 0.8rem; }

/* ===== CARDS ===== */
.card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
}
.card-header {
  padding: 16px 20px; border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
}
.card-body { padding: 20px; }
.card-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 16px;
}

/* ===== BADGE ===== */
.badge {
  display: inline-flex; align-items: center; padding: 2px 8px;
  border-radius: 10px; font-size: 0.7rem; font-weight: 600;
}
.badge-positive { background: var(--positive-bg); color: var(--positive); }
.badge-negative { background: var(--negative-bg); color: var(--negative); }
.badge-platinum { background: linear-gradient(135deg, #e5e4e2, #b0afad); color: #1a1a1a; }
.badge-gold { background: var(--gold-bg); color: var(--gold); }

/* ===== SPARKLINE ===== */
.sparkline { display: inline-block; vertical-align: middle; }

/* ===== IDEA CARD ===== */
.idea-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 20px;
  transition: border-color 0.15s;
}
.idea-card:hover { border-color: var(--border-light); }
.idea-card-header {
  display: flex; align-items: center; gap: 10px; margin-bottom: 12px;
}
.idea-avatar {
  width: 36px; height: 36px; border-radius: 50%;
  background: var(--bg-tertiary); display: flex; align-items: center;
  justify-content: center; font-weight: 600; font-size: 0.8rem; color: var(--accent);
}
.idea-author { font-weight: 600; font-size: 0.875rem; }
.idea-time { font-size: 0.75rem; color: var(--text-secondary); }
.idea-card-title {
  font-size: 0.95rem; font-weight: 600; color: var(--text-primary);
  margin-bottom: 8px; line-height: 1.4;
}
.idea-card-body { font-size: 0.85rem; color: var(--text-secondary); margin-bottom: 12px; line-height: 1.5; }
.idea-card-footer { display: flex; align-items: center; gap: 16px; }
.idea-stat {
  display: flex; align-items: center; gap: 4px;
  font-size: 0.75rem; color: var(--text-secondary);
}
.idea-stat i { font-size: 0.875rem; }

/* ===== BROKER CARD ===== */
.broker-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 24px;
  transition: border-color 0.15s;
}
.broker-card:hover { border-color: var(--accent); }
.broker-card-top { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 16px; }
.broker-info { display: flex; align-items: center; gap: 12px; }
.broker-logo {
  width: 48px; height: 48px; border-radius: var(--radius-md);
  background: var(--bg-tertiary); display: flex; align-items: center;
  justify-content: center; font-weight: 700; font-size: 0.9rem; color: var(--accent);
}
.broker-name { font-size: 1.1rem; font-weight: 600; color: var(--white); }
.broker-desc { font-size: 0.75rem; color: var(--text-secondary); margin-top: 2px; }
.broker-rating {
  display: flex; align-items: center; gap: 6px; margin-bottom: 16px;
}
.broker-stars { color: var(--gold); font-size: 0.875rem; }
.broker-score { font-weight: 600; font-size: 0.95rem; color: var(--white); }
.broker-score-label { font-size: 0.75rem; color: var(--text-secondary); }
.broker-stats {
  display: flex; gap: 24px; padding-top: 16px; border-top: 1px solid var(--border);
}
.broker-stat-label { font-size: 0.7rem; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.3px; }
.broker-stat-value { font-size: 0.95rem; font-weight: 600; color: var(--text-primary); }
.broker-promo {
  margin-top: 12px; padding: 8px 12px; background: rgba(41,98,255,0.08);
  border: 1px solid rgba(41,98,255,0.2); border-radius: var(--radius-sm);
  font-size: 0.8rem; color: var(--accent); font-weight: 500;
}

/* ===== CHART PAGE LAYOUT ===== */
.chart-workspace {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-rows: auto 1fr;
  height: calc(100vh - var(--nav-height));
}
.chart-toolbar {
  grid-column: 1 / -1;
  display: flex; align-items: center; gap: 8px;
  padding: 8px 16px; background: var(--bg-secondary);
  border-bottom: 1px solid var(--border); overflow-x: auto;
}
.chart-toolbar .ticker-info {
  display: flex; align-items: center; gap: 8px;
  margin-right: 16px; white-space: nowrap;
}
.chart-toolbar .ticker-symbol { font-size: 1.1rem; font-weight: 700; color: var(--white); }
.chart-toolbar .ticker-price { font-size: 1.1rem; font-weight: 600; }
.chart-toolbar .divider {
  width: 1px; height: 24px; background: var(--border); margin: 0 8px;
}
.tf-btn {
  padding: 4px 10px; border: none; background: transparent;
  color: var(--text-secondary); font-size: 0.75rem; font-weight: 500;
  border-radius: var(--radius-sm); transition: all 0.15s;
}
.tf-btn:hover { color: var(--text-primary); background: var(--bg-tertiary); }
.tf-btn.active { background: var(--accent); color: var(--white); }
.tool-btn {
  padding: 6px 8px; border: none; background: transparent;
  color: var(--text-secondary); border-radius: var(--radius-sm);
  transition: all 0.15s; font-size: 1rem;
}
.tool-btn:hover { color: var(--text-primary); background: var(--bg-tertiary); }

.watchlist-sidebar {
  background: var(--bg-secondary); border-right: 1px solid var(--border);
  overflow-y: auto; padding: 0;
}
.watchlist-header {
  padding: 12px 16px; font-size: 0.8rem; font-weight: 600;
  color: var(--text-secondary); text-transform: uppercase;
  letter-spacing: 0.5px; border-bottom: 1px solid var(--border);
}
.watchlist-category {
  border-bottom: 1px solid var(--border);
}
.watchlist-category-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 16px; cursor: pointer; font-size: 0.8rem;
  font-weight: 600; color: var(--text-primary); background: var(--bg-secondary);
  transition: background 0.15s; user-select: none;
}
.watchlist-category-header:hover { background: var(--bg-tertiary); }
.watchlist-category-header i {
  font-size: 0.75rem; color: var(--text-secondary);
  transition: transform 0.2s;
}
.watchlist-category-header.collapsed i { transform: rotate(-90deg); }
.watchlist-items { overflow: hidden; transition: max-height 0.25s ease; }
.watchlist-items.collapsed { max-height: 0 !important; }
.watchlist-item {
  display: grid; grid-template-columns: 1fr auto auto;
  gap: 12px; padding: 8px 16px; cursor: pointer;
  font-size: 0.8rem; transition: background 0.1s;
  border-top: 1px solid rgba(42,46,57,0.5);
}
.watchlist-item:hover { background: var(--bg-tertiary); }
.watchlist-item.active { background: rgba(41,98,255,0.1); }
.watchlist-item .symbol { font-weight: 600; color: var(--text-primary); }
.watchlist-item .last { text-align: right; color: var(--text-primary); }
.watchlist-item .chg-pct { text-align: right; font-weight: 500; min-width: 56px; }

.chart-main {
  display: grid; grid-template-rows: 1fr auto;
  overflow: hidden;
}
.chart-canvas-wrap {
  position: relative; background: var(--bg-primary);
  overflow: hidden;
}
.chart-canvas-wrap canvas { display: block; width: 100%; height: 100%; }

.chart-detail-panel {
  background: var(--bg-secondary); border-top: 1px solid var(--border);
  overflow-y: auto; max-height: 280px;
}
.detail-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12px 16px; border-bottom: 1px solid var(--border);
}
.detail-ticker { font-size: 1rem; font-weight: 700; color: var(--white); }
.detail-price-group { display: flex; align-items: baseline; gap: 12px; }
.detail-price { font-size: 1.5rem; font-weight: 700; color: var(--white); }
.detail-change { font-size: 0.95rem; font-weight: 600; }
.detail-body { display: grid; grid-template-columns: 1fr 1fr; gap: 0; }
.detail-stats { padding: 16px; border-right: 1px solid var(--border); }
.detail-financials { padding: 16px; }
.detail-row {
  display: flex; justify-content: space-between; padding: 6px 0;
  font-size: 0.8rem; border-bottom: 1px solid rgba(42,46,57,0.5);
}
.detail-row .label { color: var(--text-secondary); }
.detail-row .value { font-weight: 500; color: var(--text-primary); }
.detail-section-title {
  font-size: 0.75rem; font-weight: 600; color: var(--text-secondary);
  text-transform: uppercase; letter-spacing: 0.5px;
  margin-bottom: 8px; margin-top: 12px;
}
.detail-section-title:first-child { margin-top: 0; }
.detail-headline {
  padding: 12px 16px; font-size: 0.8rem; color: var(--text-secondary);
  border-top: 1px solid var(--border); line-height: 1.5;
}
.detail-headline i { color: var(--accent); margin-right: 4px; }

/* ===== STATS BANNER ===== */
.stats-banner {
  display: flex; align-items: center; justify-content: center; gap: 48px;
  padding: 40px 24px;
  background: linear-gradient(135deg, var(--bg-secondary) 0%, #1a1a3e 100%);
  border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
}
.stat-item { text-align: center; }
.stat-value {
  font-size: 2rem; font-weight: 700; color: var(--white);
  margin-bottom: 4px;
}
.stat-label {
  font-size: 0.85rem; color: var(--text-secondary);
}
.stat-tagline {
  font-size: 0.875rem; color: var(--accent); font-weight: 500;
  font-style: italic;
}

/* ===== FOOTER ===== */
.footer {
  background: var(--bg-secondary); border-top: 1px solid var(--border);
  padding: 48px 24px 24px;
}
.footer-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px; max-width: 1200px; margin: 0 auto 32px;
}
.footer-col h4 {
  font-size: 0.8rem; font-weight: 600; color: var(--text-primary);
  text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 12px;
}
.footer-col a {
  display: block; font-size: 0.8rem; color: var(--text-secondary);
  padding: 3px 0; transition: color 0.15s;
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  text-align: center; padding-top: 24px; border-top: 1px solid var(--border);
  font-size: 0.75rem; color: var(--text-muted);
  max-width: 1200px; margin: 0 auto;
}

/* ===== MARKETS PAGE ===== */
.markets-tabs-nav {
  display: flex; gap: 0; background: var(--bg-secondary);
  border-bottom: 1px solid var(--border); padding: 0 24px;
  overflow-x: auto;
}
.markets-tabs-nav a {
  padding: 12px 16px; font-size: 0.85rem; font-weight: 500;
  color: var(--text-secondary); white-space: nowrap;
  border-bottom: 2px solid transparent; transition: all 0.15s;
}
.markets-tabs-nav a:hover { color: var(--text-primary); }
.markets-tabs-nav a.active { color: var(--accent); border-bottom-color: var(--accent); }
.markets-section {
  padding: 24px; max-width: 1400px; margin: 0 auto;
}
.markets-section-title {
  font-size: 1.1rem; font-weight: 600; color: var(--white);
  margin-bottom: 16px; display: flex; align-items: center; gap: 8px;
}
.markets-section-title i { color: var(--accent); }

.mini-chart-controls {
  display: flex; gap: 2px; margin-bottom: 12px;
}
.mc-btn {
  padding: 4px 8px; border: none; background: transparent;
  color: var(--text-muted); font-size: 0.7rem; font-weight: 500;
  border-radius: var(--radius-sm); transition: all 0.15s;
}
.mc-btn:hover { color: var(--text-secondary); }
.mc-btn.active { background: var(--bg-tertiary); color: var(--text-primary); }

/* ===== MOVERS ===== */
.movers-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.movers-col h4 {
  font-size: 0.85rem; font-weight: 600; margin-bottom: 12px;
  display: flex; align-items: center; gap: 6px;
}
.movers-list { list-style: none; }
.movers-list li {
  display: flex; justify-content: space-between; align-items: center;
  padding: 8px 0; border-bottom: 1px solid var(--border);
  font-size: 0.85rem;
}
.movers-list .name { color: var(--text-primary); }
.movers-list .pct { font-weight: 600; }

/* ===== EARNINGS ===== */
.earnings-row {
  display: grid; grid-template-columns: auto 1fr auto auto;
  gap: 16px; padding: 10px 0; border-bottom: 1px solid var(--border);
  align-items: center; font-size: 0.85rem;
}
.earnings-date {
  font-size: 0.7rem; color: var(--text-secondary); text-transform: uppercase;
  background: var(--bg-tertiary); padding: 2px 8px; border-radius: 10px;
}
.earnings-company { font-weight: 500; }
.earnings-actual { color: var(--positive); font-weight: 500; }
.earnings-estimate { color: var(--text-secondary); }

/* ===== PAGINATION ===== */
.pagination {
  display: flex; align-items: center; justify-content: center; gap: 4px;
  padding: 24px 0;
}
.page-btn {
  width: 36px; height: 36px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary);
  border-radius: var(--radius-md); font-size: 0.85rem; font-weight: 500;
  transition: all 0.15s;
}
.page-btn:hover { border-color: var(--text-secondary); color: var(--text-primary); }
.page-btn.active { background: var(--accent); border-color: var(--accent); color: var(--white); }

/* ===== FILTER BAR ===== */
.filter-bar {
  display: flex; align-items: center; gap: 12px;
  padding: 16px 0; flex-wrap: wrap;
}
.filter-chip {
  padding: 6px 14px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary);
  border-radius: 20px; font-size: 0.8rem; font-weight: 500;
  transition: all 0.15s; white-space: nowrap;
}
.filter-chip:hover { border-color: var(--text-secondary); color: var(--text-primary); }
.filter-chip.active { background: var(--accent); border-color: var(--accent); color: var(--white); }
.toggle-filter {
  display: flex; align-items: center; gap: 6px;
  font-size: 0.8rem; color: var(--text-secondary); cursor: pointer;
}
.toggle-switch {
  position: relative; width: 36px; height: 20px;
  background: var(--bg-tertiary); border-radius: 10px;
  transition: background 0.2s;
}
.toggle-switch::after {
  content: ''; position: absolute; top: 2px; left: 2px;
  width: 16px; height: 16px; background: var(--text-secondary);
  border-radius: 50%; transition: all 0.2s;
}
.toggle-filter.active .toggle-switch { background: var(--accent); }
.toggle-filter.active .toggle-switch::after { left: 18px; background: var(--white); }

/* ===== IDEA GRID ===== */
.ideas-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 16px;
}
.idea-chart-placeholder {
  height: 140px; background: var(--bg-primary); border-radius: var(--radius-md);
  margin-bottom: 12px; overflow: hidden;
}
.idea-chart-placeholder canvas { width: 100%; height: 100%; }

/* ===== BROKER GRID ===== */
.broker-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 16px;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .chart-workspace {
    grid-template-columns: 1fr;
  }
  .watchlist-sidebar { display: none; }
  .hero h1 { font-size: 2rem; }
  .movers-grid { grid-template-columns: 1fr; }
  .detail-body { grid-template-columns: 1fr; }
  .detail-financials { border-top: 1px solid var(--border); border-left: none; }
}
@media (max-width: 768px) {
  html { font-size: 13px; }
  .navbar { padding: 0 12px; }
  .nav-links { display: none; }
  .section { padding: 20px 12px; }
  .hero { padding: 48px 16px 36px; }
  .hero h1 { font-size: 1.75rem; }
  .hero-actions { flex-direction: column; align-items: center; }
  .market-summary { padding: 0 12px; }
  .stats-banner { flex-direction: column; gap: 24px; }
  .ideas-grid, .broker-grid, .card-grid {
    grid-template-columns: 1fr;
  }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ===== ANIMATIONS ===== */
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.fade-in { animation: fadeIn 0.3s ease forwards; }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }
.pulse { animation: pulse 2s ease-in-out infinite; }

/* ChartPulse — Dark Trading Terminal Theme */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --bg-primary: #131722;
  --bg-secondary: #1e222d;
  --bg-tertiary: #2a2e39;
  --bg-hover: #363a45;
  --accent: #2962FF;
  --accent-hover: #1e53e5;
  --positive: #26a69a;
  --positive-bg: rgba(38,166,154,0.12);
  --negative: #ef5350;
  --negative-bg: rgba(239,83,80,0.12);
  --text-primary: #d1d4dc;
  --text-secondary: #787b86;
  --text-muted: #4c525e;
  --border: #2a2e39;
  --border-light: #363a45;
  --white: #ffffff;
  --gold: #f0b90b;
  --gold-bg: rgba(240,185,11,0.1);
  --platinum: #e5e4e2;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --nav-height: 56px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: var(--accent); text-decoration: none; transition: color 0.15s; }
a:hover { color: var(--accent-hover); }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; }
input, select { font-family: inherit; }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--bg-tertiary); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--bg-hover); }

/* ===== NAVIGATION ===== */
.navbar {
  position: sticky; top: 0; z-index: 100;
  display: flex; align-items: center; justify-content: space-between;
  height: var(--nav-height);
  padding: 0 24px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(12px);
}
.nav-brand {
  display: flex; align-items: center; gap: 8px;
  font-size: 1.25rem; font-weight: 700; color: var(--white);
  text-decoration: none;
}
.nav-brand i { color: var(--accent); font-size: 1.5rem; }
.nav-links { display: flex; gap: 4px; }
.nav-links a {
  padding: 8px 16px; border-radius: var(--radius-md);
  color: var(--text-secondary); font-size: 0.875rem; font-weight: 500;
  transition: all 0.15s;
}
.nav-links a:hover { color: var(--text-primary); background: var(--bg-tertiary); }
.nav-links a.active { color: var(--accent); background: rgba(41,98,255,0.1); }
.nav-right { display: flex; align-items: center; gap: 12px; }
.nav-search {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 12px; background: var(--bg-tertiary); border-radius: var(--radius-md);
  color: var(--text-secondary); font-size: 0.8rem;
}
.nav-search i { font-size: 0.875rem; }
.btn-primary {
  padding: 8px 20px; background: var(--accent); color: var(--white);
  border: none; border-radius: var(--radius-md); font-weight: 600;
  font-size: 0.875rem; transition: background 0.15s;
}
.btn-primary:hover { background: var(--accent-hover); }
.btn-outline {
  padding: 8px 20px; background: transparent; color: var(--text-primary);
  border: 1px solid var(--border-light); border-radius: var(--radius-md);
  font-weight: 500; font-size: 0.875rem; transition: all 0.15s;
}
.btn-outline:hover { border-color: var(--text-secondary); }

/* ===== HERO ===== */
.hero {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; padding: 80px 24px 60px;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}
.hero h1 {
  font-size: 2.75rem; font-weight: 700; line-height: 1.2;
  max-width: 700px; margin-bottom: 16px; color: var(--white);
}
.hero h1 span { color: var(--accent); }
.hero p {
  font-size: 1.125rem; color: var(--text-secondary);
  max-width: 560px; margin-bottom: 32px; line-height: 1.6;
}
.hero-actions { display: flex; gap: 12px; }
.hero .btn-primary { padding: 12px 32px; font-size: 1rem; }
.hero .btn-outline { padding: 12px 32px; font-size: 1rem; }

/* ===== MARKET SUMMARY BAR ===== */
.market-summary {
  display: flex; gap: 0; padding: 0 24px;
  background: var(--bg-secondary); border-bottom: 1px solid var(--border);
  overflow-x: auto;
}
.market-summary-item {
  display: flex; flex-direction: column; padding: 12px 20px;
  border-right: 1px solid var(--border); min-width: 140px;
  white-space: nowrap;
}
.market-summary-item:last-child { border-right: none; }
.market-summary-item .label {
  font-size: 0.7rem; color: var(--text-secondary);
  text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 2px;
}
.market-summary-item .price {
  font-size: 0.95rem; font-weight: 600; color: var(--text-primary);
}
.market-summary-item .change { font-size: 0.75rem; font-weight: 500; }
.change.positive { color: var(--positive); }
.change.negative { color: var(--negative); }

/* ===== SECTION LAYOUT ===== */
.section {
  padding: 32px 24px;
  max-width: 1400px;
  margin: 0 auto;
}
.section-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 20px;
}
.section-title {
  font-size: 1.25rem; font-weight: 600; color: var(--white);
}

/* ===== TABS ===== */
.tabs {
  display: flex; gap: 2px; background: var(--bg-tertiary);
  border-radius: var(--radius-md); padding: 2px;
}
.tab-btn {
  padding: 6px 14px; border: none; background: transparent;
  color: var(--text-secondary); font-size: 0.8rem; font-weight: 500;
  border-radius: var(--radius-sm); transition: all 0.15s; white-space: nowrap;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active {
  background: var(--accent); color: var(--white);
}
.tabs-simple { display: flex; gap: 16px; }
.tabs-simple .tab-btn {
  padding: 4px 0; border: none; background: transparent;
  color: var(--text-secondary); font-size: 0.875rem; font-weight: 500;
  border-bottom: 2px solid transparent; border-radius: 0;
  transition: all 0.15s;
}
.tabs-simple .tab-btn:hover { color: var(--text-primary); }
.tabs-simple .tab-btn.active {
  color: var(--accent); border-bottom-color: var(--accent);
}

/* ===== TAB PANELS ===== */
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ===== DATA TABLES ===== */
.data-table {
  width: 100%; border-collapse: collapse; font-size: 0.85rem;
}
.data-table th {
  text-align: left; padding: 10px 12px; font-weight: 500;
  color: var(--text-secondary); border-bottom: 1px solid var(--border);
  font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.5px;
  position: sticky; top: 0; background: var(--bg-secondary);
}
.data-table td {
  padding: 10px 12px; border-bottom: 1px solid var(--border);
  vertical-align: middle;
}
.data-table tr:hover td { background: var(--bg-tertiary); }
.data-table .ticker {
  font-weight: 600; color: var(--text-primary);
}
.data-table .company { color: var(--text-secondary); font-size: 0.8rem; }

/* ===== CARDS ===== */
.card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
}
.card-header {
  padding: 16px 20px; border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
}
.card-body { padding: 20px; }
.card-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 16px;
}

/* ===== BADGE ===== */
.badge {
  display: inline-flex; align-items: center; padding: 2px 8px;
  border-radius: 10px; font-size: 0.7rem; font-weight: 600;
}
.badge-positive { background: var(--positive-bg); color: var(--positive); }
.badge-negative { background: var(--negative-bg); color: var(--negative); }
.badge-platinum { background: linear-gradient(135deg, #e5e4e2, #b0afad); color: #1a1a1a; }
.badge-gold { background: var(--gold-bg); color: var(--gold); }

/* ===== SPARKLINE ===== */
.sparkline { display: inline-block; vertical-align: middle; }

/* ===== IDEA CARD ===== */
.idea-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 20px;
  transition: border-color 0.15s;
}
.idea-card:hover { border-color: var(--border-light); }
.idea-card-header {
  display: flex; align-items: center; gap: 10px; margin-bottom: 12px;
}
.idea-avatar {
  width: 36px; height: 36px; border-radius: 50%;
  background: var(--bg-tertiary); display: flex; align-items: center;
  justify-content: center; font-weight: 600; font-size: 0.8rem; color: var(--accent);
}
.idea-author { font-weight: 600; font-size: 0.875rem; }
.idea-time { font-size: 0.75rem; color: var(--text-secondary); }
.idea-card-title {
  font-size: 0.95rem; font-weight: 600; color: var(--text-primary);
  margin-bottom: 8px; line-height: 1.4;
}
.idea-card-body { font-size: 0.85rem; color: var(--text-secondary); margin-bottom: 12px; line-height: 1.5; }
.idea-card-footer { display: flex; align-items: center; gap: 16px; }
.idea-stat {
  display: flex; align-items: center; gap: 4px;
  font-size: 0.75rem; color: var(--text-secondary);
}
.idea-stat i { font-size: 0.875rem; }

/* ===== BROKER CARD ===== */
.broker-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 24px;
  transition: border-color 0.15s;
}
.broker-card:hover { border-color: var(--accent); }
.broker-card-top { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 16px; }
.broker-info { display: flex; align-items: center; gap: 12px; }
.broker-logo {
  width: 48px; height: 48px; border-radius: var(--radius-md);
  background: var(--bg-tertiary); display: flex; align-items: center;
  justify-content: center; font-weight: 700; font-size: 0.9rem; color: var(--accent);
}
.broker-name { font-size: 1.1rem; font-weight: 600; color: var(--white); }
.broker-desc { font-size: 0.75rem; color: var(--text-secondary); margin-top: 2px; }
.broker-rating {
  display: flex; align-items: center; gap: 6px; margin-bottom: 16px;
}
.broker-stars { color: var(--gold); font-size: 0.875rem; }
.broker-score { font-weight: 600; font-size: 0.95rem; color: var(--white); }
.broker-score-label { font-size: 0.75rem; color: var(--text-secondary); }
.broker-stats {
  display: flex; gap: 24px; padding-top: 16px; border-top: 1px solid var(--border);
}
.broker-stat-label { font-size: 0.7rem; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.3px; }
.broker-stat-value { font-size: 0.95rem; font-weight: 600; color: var(--text-primary); }
.broker-promo {
  margin-top: 12px; padding: 8px 12px; background: rgba(41,98,255,0.08);
  border: 1px solid rgba(41,98,255,0.2); border-radius: var(--radius-sm);
  font-size: 0.8rem; color: var(--accent); font-weight: 500;
}

/* ===== CHART PAGE LAYOUT ===== */
.chart-workspace {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-rows: auto 1fr;
  height: calc(100vh - var(--nav-height));
}
.chart-toolbar {
  grid-column: 1 / -1;
  display: flex; align-items: center; gap: 8px;
  padding: 8px 16px; background: var(--bg-secondary);
  border-bottom: 1px solid var(--border); overflow-x: auto;
}
.chart-toolbar .ticker-info {
  display: flex; align-items: center; gap: 8px;
  margin-right: 16px; white-space: nowrap;
}
.chart-toolbar .ticker-symbol { font-size: 1.1rem; font-weight: 700; color: var(--white); }
.chart-toolbar .ticker-price { font-size: 1.1rem; font-weight: 600; }
.chart-toolbar .divider {
  width: 1px; height: 24px; background: var(--border); margin: 0 8px;
}
.tf-btn {
  padding: 4px 10px; border: none; background: transparent;
  color: var(--text-secondary); font-size: 0.75rem; font-weight: 500;
  border-radius: var(--radius-sm); transition: all 0.15s;
}
.tf-btn:hover { color: var(--text-primary); background: var(--bg-tertiary); }
.tf-btn.active { background: var(--accent); color: var(--white); }
.tool-btn {
  padding: 6px 8px; border: none; background: transparent;
  color: var(--text-secondary); border-radius: var(--radius-sm);
  transition: all 0.15s; font-size: 1rem;
}
.tool-btn:hover { color: var(--text-primary); background: var(--bg-tertiary); }

.watchlist-sidebar {
  background: var(--bg-secondary); border-right: 1px solid var(--border);
  overflow-y: auto; padding: 0;
}
.watchlist-header {
  padding: 12px 16px; font-size: 0.8rem; font-weight: 600;
  color: var(--text-secondary); text-transform: uppercase;
  letter-spacing: 0.5px; border-bottom: 1px solid var(--border);
}
.watchlist-category {
  border-bottom: 1px solid var(--border);
}
.watchlist-category-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 16px; cursor: pointer; font-size: 0.8rem;
  font-weight: 600; color: var(--text-primary); background: var(--bg-secondary);
  transition: background 0.15s; user-select: none;
}
.watchlist-category-header:hover { background: var(--bg-tertiary); }
.watchlist-category-header i {
  font-size: 0.75rem; color: var(--text-secondary);
  transition: transform 0.2s;
}
.watchlist-category-header.collapsed i { transform: rotate(-90deg); }
.watchlist-items { overflow: hidden; transition: max-height 0.25s ease; }
.watchlist-items.collapsed { max-height: 0 !important; }
.watchlist-item {
  display: grid; grid-template-columns: 1fr auto auto;
  gap: 12px; padding: 8px 16px; cursor: pointer;
  font-size: 0.8rem; transition: background 0.1s;
  border-top: 1px solid rgba(42,46,57,0.5);
}
.watchlist-item:hover { background: var(--bg-tertiary); }
.watchlist-item.active { background: rgba(41,98,255,0.1); }
.watchlist-item .symbol { font-weight: 600; color: var(--text-primary); }
.watchlist-item .last { text-align: right; color: var(--text-primary); }
.watchlist-item .chg-pct { text-align: right; font-weight: 500; min-width: 56px; }

.chart-main {
  display: grid; grid-template-rows: 1fr auto;
  overflow: hidden;
}
.chart-canvas-wrap {
  position: relative; background: var(--bg-primary);
  overflow: hidden;
}
.chart-canvas-wrap canvas { display: block; width: 100%; height: 100%; }

.chart-detail-panel {
  background: var(--bg-secondary); border-top: 1px solid var(--border);
  overflow-y: auto; max-height: 280px;
}
.detail-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12px 16px; border-bottom: 1px solid var(--border);
}
.detail-ticker { font-size: 1rem; font-weight: 700; color: var(--white); }
.detail-price-group { display: flex; align-items: baseline; gap: 12px; }
.detail-price { font-size: 1.5rem; font-weight: 700; color: var(--white); }
.detail-change { font-size: 0.95rem; font-weight: 600; }
.detail-body { display: grid; grid-template-columns: 1fr 1fr; gap: 0; }
.detail-stats { padding: 16px; border-right: 1px solid var(--border); }
.detail-financials { padding: 16px; }
.detail-row {
  display: flex; justify-content: space-between; padding: 6px 0;
  font-size: 0.8rem; border-bottom: 1px solid rgba(42,46,57,0.5);
}
.detail-row .label { color: var(--text-secondary); }
.detail-row .value { font-weight: 500; color: var(--text-primary); }
.detail-section-title {
  font-size: 0.75rem; font-weight: 600; color: var(--text-secondary);
  text-transform: uppercase; letter-spacing: 0.5px;
  margin-bottom: 8px; margin-top: 12px;
}
.detail-section-title:first-child { margin-top: 0; }
.detail-headline {
  padding: 12px 16px; font-size: 0.8rem; color: var(--text-secondary);
  border-top: 1px solid var(--border); line-height: 1.5;
}
.detail-headline i { color: var(--accent); margin-right: 4px; }

/* ===== STATS BANNER ===== */
.stats-banner {
  display: flex; align-items: center; justify-content: center; gap: 48px;
  padding: 40px 24px;
  background: linear-gradient(135deg, var(--bg-secondary) 0%, #1a1a3e 100%);
  border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
}
.stat-item { text-align: center; }
.stat-value {
  font-size: 2rem; font-weight: 700; color: var(--white);
  margin-bottom: 4px;
}
.stat-label {
  font-size: 0.85rem; color: var(--text-secondary);
}
.stat-tagline {
  font-size: 0.875rem; color: var(--accent); font-weight: 500;
  font-style: italic;
}

/* ===== FOOTER ===== */
.footer {
  background: var(--bg-secondary); border-top: 1px solid var(--border);
  padding: 48px 24px 24px;
}
.footer-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px; max-width: 1200px; margin: 0 auto 32px;
}
.footer-col h4 {
  font-size: 0.8rem; font-weight: 600; color: var(--text-primary);
  text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 12px;
}
.footer-col a {
  display: block; font-size: 0.8rem; color: var(--text-secondary);
  padding: 3px 0; transition: color 0.15s;
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  text-align: center; padding-top: 24px; border-top: 1px solid var(--border);
  font-size: 0.75rem; color: var(--text-muted);
  max-width: 1200px; margin: 0 auto;
}

/* ===== MARKETS PAGE ===== */
.markets-tabs-nav {
  display: flex; gap: 0; background: var(--bg-secondary);
  border-bottom: 1px solid var(--border); padding: 0 24px;
  overflow-x: auto;
}
.markets-tabs-nav a {
  padding: 12px 16px; font-size: 0.85rem; font-weight: 500;
  color: var(--text-secondary); white-space: nowrap;
  border-bottom: 2px solid transparent; transition: all 0.15s;
}
.markets-tabs-nav a:hover { color: var(--text-primary); }
.markets-tabs-nav a.active { color: var(--accent); border-bottom-color: var(--accent); }
.markets-section {
  padding: 24px; max-width: 1400px; margin: 0 auto;
}
.markets-section-title {
  font-size: 1.1rem; font-weight: 600; color: var(--white);
  margin-bottom: 16px; display: flex; align-items: center; gap: 8px;
}
.markets-section-title i { color: var(--accent); }

.mini-chart-controls {
  display: flex; gap: 2px; margin-bottom: 12px;
}
.mc-btn {
  padding: 4px 8px; border: none; background: transparent;
  color: var(--text-muted); font-size: 0.7rem; font-weight: 500;
  border-radius: var(--radius-sm); transition: all 0.15s;
}
.mc-btn:hover { color: var(--text-secondary); }
.mc-btn.active { background: var(--bg-tertiary); color: var(--text-primary); }

/* ===== MOVERS ===== */
.movers-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.movers-col h4 {
  font-size: 0.85rem; font-weight: 600; margin-bottom: 12px;
  display: flex; align-items: center; gap: 6px;
}
.movers-list { list-style: none; }
.movers-list li {
  display: flex; justify-content: space-between; align-items: center;
  padding: 8px 0; border-bottom: 1px solid var(--border);
  font-size: 0.85rem;
}
.movers-list .name { color: var(--text-primary); }
.movers-list .pct { font-weight: 600; }

/* ===== EARNINGS ===== */
.earnings-row {
  display: grid; grid-template-columns: auto 1fr auto auto;
  gap: 16px; padding: 10px 0; border-bottom: 1px solid var(--border);
  align-items: center; font-size: 0.85rem;
}
.earnings-date {
  font-size: 0.7rem; color: var(--text-secondary); text-transform: uppercase;
  background: var(--bg-tertiary); padding: 2px 8px; border-radius: 10px;
}
.earnings-company { font-weight: 500; }
.earnings-actual { color: var(--positive); font-weight: 500; }
.earnings-estimate { color: var(--text-secondary); }

/* ===== PAGINATION ===== */
.pagination {
  display: flex; align-items: center; justify-content: center; gap: 4px;
  padding: 24px 0;
}
.page-btn {
  width: 36px; height: 36px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary);
  border-radius: var(--radius-md); font-size: 0.85rem; font-weight: 500;
  transition: all 0.15s;
}
.page-btn:hover { border-color: var(--text-secondary); color: var(--text-primary); }
.page-btn.active { background: var(--accent); border-color: var(--accent); color: var(--white); }

/* ===== FILTER BAR ===== */
.filter-bar {
  display: flex; align-items: center; gap: 12px;
  padding: 16px 0; flex-wrap: wrap;
}
.filter-chip {
  padding: 6px 14px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary);
  border-radius: 20px; font-size: 0.8rem; font-weight: 500;
  transition: all 0.15s; white-space: nowrap;
}
.filter-chip:hover { border-color: var(--text-secondary); color: var(--text-primary); }
.filter-chip.active { background: var(--accent); border-color: var(--accent); color: var(--white); }
.toggle-filter {
  display: flex; align-items: center; gap: 6px;
  font-size: 0.8rem; color: var(--text-secondary); cursor: pointer;
}
.toggle-switch {
  position: relative; width: 36px; height: 20px;
  background: var(--bg-tertiary); border-radius: 10px;
  transition: background 0.2s;
}
.toggle-switch::after {
  content: ''; position: absolute; top: 2px; left: 2px;
  width: 16px; height: 16px; background: var(--text-secondary);
  border-radius: 50%; transition: all 0.2s;
}
.toggle-filter.active .toggle-switch { background: var(--accent); }
.toggle-filter.active .toggle-switch::after { left: 18px; background: var(--white); }

/* ===== IDEA GRID ===== */
.ideas-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 16px;
}
.idea-chart-placeholder {
  height: 140px; background: var(--bg-primary); border-radius: var(--radius-md);
  margin-bottom: 12px; overflow: hidden;
}
.idea-chart-placeholder canvas { width: 100%; height: 100%; }

/* ===== BROKER GRID ===== */
.broker-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 16px;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .chart-workspace {
    grid-template-columns: 1fr;
  }
  .watchlist-sidebar { display: none; }
  .hero h1 { font-size: 2rem; }
  .movers-grid { grid-template-columns: 1fr; }
  .detail-body { grid-template-columns: 1fr; }
  .detail-financials { border-top: 1px solid var(--border); border-left: none; }
}
@media (max-width: 768px) {
  html { font-size: 13px; }
  .navbar { padding: 0 12px; }
  .nav-links { display: none; }
  .section { padding: 20px 12px; }
  .hero { padding: 48px 16px 36px; }
  .hero h1 { font-size: 1.75rem; }
  .hero-actions { flex-direction: column; align-items: center; }
  .market-summary { padding: 0 12px; }
  .stats-banner { flex-direction: column; gap: 24px; }
  .ideas-grid, .broker-grid, .card-grid {
    grid-template-columns: 1fr;
  }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ===== ANIMATIONS ===== */
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.fade-in { animation: fadeIn 0.3s ease forwards; }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }
.pulse { animation: pulse 2s ease-in-out infinite; }

raw_arguments.content:
/* ChartPulse — Dark Trading Terminal Theme */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --bg-primary: #131722;
  --bg-secondary: #1e222d;
  --bg-tertiary: #2a2e39;
  --bg-hover: #363a45;
  --accent: #2962FF;
  --accent-hover: #1e53e5;
  --positive: #26a69a;
  --positive-bg: rgba(38,166,154,0.12);
  --negative: #ef5350;
  --negative-bg: rgba(239,83,80,0.12);
  --text-primary: #d1d4dc;
  --text-secondary: #787b86;
  --text-muted: #4c525e;
  --border: #2a2e39;
  --border-light: #363a45;
  --white: #ffffff;
  --gold: #f0b90b;
  --gold-bg: rgba(240,185,11,0.1);
  --platinum: #e5e4e2;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --nav-height: 56px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: var(--accent); text-decoration: none; transition: color 0.15s; }
a:hover { color: var(--accent-hover); }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; }
input, select { font-family: inherit; }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--bg-tertiary); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--bg-hover); }

/* ===== NAVIGATION ===== */
.navbar {
  position: sticky; top: 0; z-index: 100;
  display: flex; align-items: center; justify-content: space-between;
  height: var(--nav-height);
  padding: 0 24px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(12px);
}
.nav-brand {
  display: flex; align-items: center; gap: 8px;
  font-size: 1.25rem; font-weight: 700; color: var(--white);
  text-decoration: none;
}
.nav-brand i { color: var(--accent); font-size: 1.5rem; }
.nav-links { display: flex; gap: 4px; }
.nav-links a {
  padding: 8px 16px; border-radius: var(--radius-md);
  color: var(--text-secondary); font-size: 0.875rem; font-weight: 500;
  transition: all 0.15s;
}
.nav-links a:hover { color: var(--text-primary); background: var(--bg-tertiary); }
.nav-links a.active { color: var(--accent); background: rgba(41,98,255,0.1); }
.nav-right { display: flex; align-items: center; gap: 12px; }
.nav-search {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 12px; background: var(--bg-tertiary); border-radius: var(--radius-md);
  color: var(--text-secondary); font-size: 0.8rem;
}
.nav-search i { font-size: 0.875rem; }
.btn-primary {
  padding: 8px 20px; background: var(--accent); color: var(--white);
  border: none; border-radius: var(--radius-md); font-weight: 600;
  font-size: 0.875rem; transition: background 0.15s;
}
.btn-primary:hover { background: var(--accent-hover); }
.btn-outline {
  padding: 8px 20px; background: transparent; color: var(--text-primary);
  border: 1px solid var(--border-light); border-radius: var(--radius-md);
  font-weight: 500; font-size: 0.875rem; transition: all 0.15s;
}
.btn-outline:hover { border-color: var(--text-secondary); }

/* ===== HERO ===== */
.hero {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; padding: 80px 24px 60px;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}
.hero h1 {
  font-size: 2.75rem; font-weight: 700; line-height: 1.2;
  max-width: 700px; margin-bottom: 16px; color: var(--white);
}
.hero h1 span { color: var(--accent); }
.hero p {
  font-size: 1.125rem; color: var(--text-secondary);
  max-width: 560px; margin-bottom: 32px; line-height: 1.6;
}
.hero-actions { display: flex; gap: 12px; }
.hero .btn-primary { padding: 12px 32px; font-size: 1rem; }
.hero .btn-outline { padding: 12px 32px; font-size: 1rem; }

/* ===== MARKET SUMMARY BAR ===== */
.market-summary {
  display: flex; gap: 0; padding: 0 24px;
  background: var(--bg-secondary); border-bottom: 1px solid var(--border);
  overflow-x: auto;
}
.market-summary-item {
  display: flex; flex-direction: column; padding: 12px 20px;
  border-right: 1px solid var(--border); min-width: 140px;
  white-space: nowrap;
}
.market-summary-item:last-child { border-right: none; }
.market-summary-item .label {
  font-size: 0.7rem; color: var(--text-secondary);
  text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 2px;
}
.market-summary-item .price {
  font-size: 0.95rem; font-weight: 600; color: var(--text-primary);
}
.market-summary-item .change { font-size: 0.75rem; font-weight: 500; }
.change.positive { color: var(--positive); }
.change.negative { color: var(--negative); }

/* ===== SECTION LAYOUT ===== */
.section {
  padding: 32px 24px;
  max-width: 1400px;
  margin: 0 auto;
}
.section-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 20px;
}
.section-title {
  font-size: 1.25rem; font-weight: 600; color: var(--white);
}

/* ===== TABS ===== */
.tabs {
  display: flex; gap: 2px; background: var(--bg-tertiary);
  border-radius: var(--radius-md); padding: 2px;
}
.tab-btn {
  padding: 6px 14px; border: none; background: transparent;
  color: var(--text-secondary); font-size: 0.8rem; font-weight: 500;
  border-radius: var(--radius-sm); transition: all 0.15s; white-space: nowrap;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active {
  background: var(--accent); color: var(--white);
}
.tabs-simple { display: flex; gap: 16px; }
.tabs-simple .tab-btn {
  padding: 4px 0; border: none; background: transparent;
  color: var(--text-secondary); font-size: 0.875rem; font-weight: 500;
  border-bottom: 2px solid transparent; border-radius: 0;
  transition: all 0.15s;
}
.tabs-simple .tab-btn:hover { color: var(--text-primary); }
.tabs-simple .tab-btn.active {
  color: var(--accent); border-bottom-color: var(--accent);
}

/* ===== TAB PANELS ===== */
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ===== DATA TABLES ===== */
.data-table {
  width: 100%; border-collapse: collapse; font-size: 0.85rem;
}
.data-table th {
  text-align: left; padding: 10px 12px; font-weight: 500;
  color: var(--text-secondary); border-bottom: 1px solid var(--border);
  font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.5px;
  position: sticky; top: 0; background: var(--bg-secondary);
}
.data-table td {
  padding: 10px 12px; border-bottom: 1px solid var(--border);
  vertical-align: middle;
}
.data-table tr:hover td { background: var(--bg-tertiary); }
.data-table .ticker {
  font-weight: 600; color: var(--text-primary);
}
.data-table .company { color: var(--text-secondary); font-size: 0.8rem; }

/* ===== CARDS ===== */
.card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
}
.card-header {
  padding: 16px 20px; border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
}
.card-body { padding: 20px; }
.card-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 16px;
}

/* ===== BADGE ===== */
.badge {
  display: inline-flex; align-items: center; padding: 2px 8px;
  border-radius: 10px; font-size: 0.7rem; font-weight: 600;
}
.badge-positive { background: var(--positive-bg); color: var(--positive); }
.badge-negative { background: var(--negative-bg); color: var(--negative); }
.badge-platinum { background: linear-gradient(135deg, #e5e4e2, #b0afad); color: #1a1a1a; }
.badge-gold { background: var(--gold-bg); color: var(--gold); }

/* ===== SPARKLINE ===== */
.sparkline { display: inline-block; vertical-align: middle; }

/* ===== IDEA CARD ===== */
.idea-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 20px;
  transition: border-color 0.15s;
}
.idea-card:hover { border-color: var(--border-light); }
.idea-card-header {
  display: flex; align-items: center; gap: 10px; margin-bottom: 12px;
}
.idea-avatar {
  width: 36px; height: 36px; border-radius: 50%;
  background: var(--bg-tertiary); display: flex; align-items: center;
  justify-content: center; font-weight: 600; font-size: 0.8rem; color: var(--accent);
}
.idea-author { font-weight: 600; font-size: 0.875rem; }
.idea-time { font-size: 0.75rem; color: var(--text-secondary); }
.idea-card-title {
  font-size: 0.95rem; font-weight: 600; color: var(--text-primary);
  margin-bottom: 8px; line-height: 1.4;
}
.idea-card-body { font-size: 0.85rem; color: var(--text-secondary); margin-bottom: 12px; line-height: 1.5; }
.idea-card-footer { display: flex; align-items: center; gap: 16px; }
.idea-stat {
  display: flex; align-items: center; gap: 4px;
  font-size: 0.75rem; color: var(--text-secondary);
}
.idea-stat i { font-size: 0.875rem; }

/* ===== BROKER CARD ===== */
.broker-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 24px;
  transition: border-color 0.15s;
}
.broker-card:hover { border-color: var(--accent); }
.broker-card-top { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 16px; }
.broker-info { display: flex; align-items: center; gap: 12px; }
.broker-logo {
  width: 48px; height: 48px; border-radius: var(--radius-md);
  background: var(--bg-tertiary); display: flex; align-items: center;
  justify-content: center; font-weight: 700; font-size: 0.9rem; color: var(--accent);
}
.broker-name { font-size: 1.1rem; font-weight: 600; color: var(--white); }
.broker-desc { font-size: 0.75rem; color: var(--text-secondary); margin-top: 2px; }
.broker-rating {
  display: flex; align-items: center; gap: 6px; margin-bottom: 16px;
}
.broker-stars { color: var(--gold); font-size: 0.875rem; }
.broker-score { font-weight: 600; font-size: 0.95rem; color: var(--white); }
.broker-score-label { font-size: 0.75rem; color: var(--text-secondary); }
.broker-stats {
  display: flex; gap: 24px; padding-top: 16px; border-top: 1px solid var(--border);
}
.broker-stat-label { font-size: 0.7rem; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.3px; }
.broker-stat-value { font-size: 0.95rem; font-weight: 600; color: var(--text-primary); }
.broker-promo {
  margin-top: 12px; padding: 8px 12px; background: rgba(41,98,255,0.08);
  border: 1px solid rgba(41,98,255,0.2); border-radius: var(--radius-sm);
  font-size: 0.8rem; color: var(--accent); font-weight: 500;
}

/* ===== CHART PAGE LAYOUT ===== */
.chart-workspace {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-rows: auto 1fr;
  height: calc(100vh - var(--nav-height));
}
.chart-toolbar {
  grid-column: 1 / -1;
  display: flex; align-items: center; gap: 8px;
  padding: 8px 16px; background: var(--bg-secondary);
  border-bottom: 1px solid var(--border); overflow-x: auto;
}
.chart-toolbar .ticker-info {
  display: flex; align-items: center; gap: 8px;
  margin-right: 16px; white-space: nowrap;
}
.chart-toolbar .ticker-symbol { font-size: 1.1rem; font-weight: 700; color: var(--white); }
.chart-toolbar .ticker-price { font-size: 1.1rem; font-weight: 600; }
.chart-toolbar .divider {
  width: 1px; height: 24px; background: var(--border); margin: 0 8px;
}
.tf-btn {
  padding: 4px 10px; border: none; background: transparent;
  color: var(--text-secondary); font-size: 0.75rem; font-weight: 500;
  border-radius: var(--radius-sm); transition: all 0.15s;
}
.tf-btn:hover { color: var(--text-primary); background: var(--bg-tertiary); }
.tf-btn.active { background: var(--accent); color: var(--white); }
.tool-btn {
  padding: 6px 8px; border: none; background: transparent;
  color: var(--text-secondary); border-radius: var(--radius-sm);
  transition: all 0.15s; font-size: 1rem;
}
.tool-btn:hover { color: var(--text-primary); background: var(--bg-tertiary); }

.watchlist-sidebar {
  background: var(--bg-secondary); border-right: 1px solid var(--border);
  overflow-y: auto; padding: 0;
}
.watchlist-header {
  padding: 12px 16px; font-size: 0.8rem; font-weight: 600;
  color: var(--text-secondary); text-transform: uppercase;
  letter-spacing: 0.5px; border-bottom: 1px solid var(--border);
}
.watchlist-category {
  border-bottom: 1px solid var(--border);
}
.watchlist-category-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 16px; cursor: pointer; font-size: 0.8rem;
  font-weight: 600; color: var(--text-primary); background: var(--bg-secondary);
  transition: background 0.15s; user-select: none;
}
.watchlist-category-header:hover { background: var(--bg-tertiary); }
.watchlist-category-header i {
  font-size: 0.75rem; color: var(--text-secondary);
  transition: transform 0.2s;
}
.watchlist-category-header.collapsed i { transform: rotate(-90deg); }
.watchlist-items { overflow: hidden; transition: max-height 0.25s ease; }
.watchlist-items.collapsed { max-height: 0 !important; }
.watchlist-item {
  display: grid; grid-template-columns: 1fr auto auto;
  gap: 12px; padding: 8px 16px; cursor: pointer;
  font-size: 0.8rem; transition: background 0.1s;
  border-top: 1px solid rgba(42,46,57,0.5);
}
.watchlist-item:hover { background: var(--bg-tertiary); }
.watchlist-item.active { background: rgba(41,98,255,0.1); }
.watchlist-item .symbol { font-weight: 600; color: var(--text-primary); }
.watchlist-item .last { text-align: right; color: var(--text-primary); }
.watchlist-item .chg-pct { text-align: right; font-weight: 500; min-width: 56px; }

.chart-main {
  display: grid; grid-template-rows: 1fr auto;
  overflow: hidden;
}
.chart-canvas-wrap {
  position: relative; background: var(--bg-primary);
  overflow: hidden;
}
.chart-canvas-wrap canvas { display: block; width: 100%; height: 100%; }

.chart-detail-panel {
  background: var(--bg-secondary); border-top: 1px solid var(--border);
  overflow-y: auto; max-height: 280px;
}
.detail-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12px 16px; border-bottom: 1px solid var(--border);
}
.detail-ticker { font-size: 1rem; font-weight: 700; color: var(--white); }
.detail-price-group { display: flex; align-items: baseline; gap: 12px; }
.detail-price { font-size: 1.5rem; font-weight: 700; color: var(--white); }
.detail-change { font-size: 0.95rem; font-weight: 600; }
.detail-body { display: grid; grid-template-columns: 1fr 1fr; gap: 0; }
.detail-stats { padding: 16px; border-right: 1px solid var(--border); }
.detail-financials { padding: 16px; }
.detail-row {
  display: flex; justify-content: space-between; padding: 6px 0;
  font-size: 0.8rem; border-bottom: 1px solid rgba(42,46,57,0.5);
}
.detail-row .label { color: var(--text-secondary); }
.detail-row .value { font-weight: 500; color: var(--text-primary); }
.detail-section-title {
  font-size: 0.75rem; font-weight: 600; color: var(--text-secondary);
  text-transform: uppercase; letter-spacing: 0.5px;
  margin-bottom: 8px; margin-top: 12px;
}
.detail-section-title:first-child { margin-top: 0; }
.detail-headline {
  padding: 12px 16px; font-size: 0.8rem; color: var(--text-secondary);
  border-top: 1px solid var(--border); line-height: 1.5;
}
.detail-headline i { color: var(--accent); margin-right: 4px; }

/* ===== STATS BANNER ===== */
.stats-banner {
  display: flex; align-items: center; justify-content: center; gap: 48px;
  padding: 40px 24px;
  background: linear-gradient(135deg, var(--bg-secondary) 0%, #1a1a3e 100%);
  border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
}
.stat-item { text-align: center; }
.stat-value {
  font-size: 2rem; font-weight: 700; color: var(--white);
  margin-bottom: 4px;
}
.stat-label {
  font-size: 0.85rem; color: var(--text-secondary);
}
.stat-tagline {
  font-size: 0.875rem; color: var(--accent); font-weight: 500;
  font-style: italic;
}

/* ===== FOOTER ===== */
.footer {
  background: var(--bg-secondary); border-top: 1px solid var(--border);
  padding: 48px 24px 24px;
}
.footer-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px; max-width: 1200px; margin: 0 auto 32px;
}
.footer-col h4 {
  font-size: 0.8rem; font-weight: 600; color: var(--text-primary);
  text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 12px;
}
.footer-col a {
  display: block; font-size: 0.8rem; color: var(--text-secondary);
  padding: 3px 0; transition: color 0.15s;
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  text-align: center; padding-top: 24px; border-top: 1px solid var(--border);
  font-size: 0.75rem; color: var(--text-muted);
  max-width: 1200px; margin: 0 auto;
}

/* ===== MARKETS PAGE ===== */
.markets-tabs-nav {
  display: flex; gap: 0; background: var(--bg-secondary);
  border-bottom: 1px solid var(--border); padding: 0 24px;
  overflow-x: auto;
}
.markets-tabs-nav a {
  padding: 12px 16px; font-size: 0.85rem; font-weight: 500;
  color: var(--text-secondary); white-space: nowrap;
  border-bottom: 2px solid transparent; transition: all 0.15s;
}
.markets-tabs-nav a:hover { color: var(--text-primary); }
.markets-tabs-nav a.active { color: var(--accent); border-bottom-color: var(--accent); }
.markets-section {
  padding: 24px; max-width: 1400px; margin: 0 auto;
}
.markets-section-title {
  font-size: 1.1rem; font-weight: 600; color: var(--white);
  margin-bottom: 16px; display: flex; align-items: center; gap: 8px;
}
.markets-section-title i { color: var(--accent); }

.mini-chart-controls {
  display: flex; gap: 2px; margin-bottom: 12px;
}
.mc-btn {
  padding: 4px 8px; border: none; background: transparent;
  color: var(--text-muted); font-size: 0.7rem; font-weight: 500;
  border-radius: var(--radius-sm); transition: all 0.15s;
}
.mc-btn:hover { color: var(--text-secondary); }
.mc-btn.active { background: var(--bg-tertiary); color: var(--text-primary); }

/* ===== MOVERS ===== */
.movers-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.movers-col h4 {
  font-size: 0.85rem; font-weight: 600; margin-bottom: 12px;
  display: flex; align-items: center; gap: 6px;
}
.movers-list { list-style: none; }
.movers-list li {
  display: flex; justify-content: space-between; align-items: center;
  padding: 8px 0; border-bottom: 1px solid var(--border);
  font-size: 0.85rem;
}
.movers-list .name { color: var(--text-primary); }
.movers-list .pct { font-weight: 600; }

/* ===== EARNINGS ===== */
.earnings-row {
  display: grid; grid-template-columns: auto 1fr auto auto;
  gap: 16px; padding: 10px 0; border-bottom: 1px solid var(--border);
  align-items: center; font-size: 0.85rem;
}
.earnings-date {
  font-size: 0.7rem; color: var(--text-secondary); text-transform: uppercase;
  background: var(--bg-tertiary); padding: 2px 8px; border-radius: 10px;
}
.earnings-company { font-weight: 500; }
.earnings-actual { color: var(--positive); font-weight: 500; }
.earnings-estimate { color: var(--text-secondary); }

/* ===== PAGINATION ===== */
.pagination {
  display: flex; align-items: center; justify-content: center; gap: 4px;
  padding: 24px 0;
}
.page-btn {
  width: 36px; height: 36px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary);
  border-radius: var(--radius-md); font-size: 0.85rem; font-weight: 500;
  transition: all 0.15s;
}
.page-btn:hover { border-color: var(--text-secondary); color: var(--text-primary); }
.page-btn.active { background: var(--accent); border-color: var(--accent); color: var(--white); }

/* ===== FILTER BAR ===== */
.filter-bar {
  display: flex; align-items: center; gap: 12px;
  padding: 16px 0; flex-wrap: wrap;
}
.filter-chip {
  padding: 6px 14px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary);
  border-radius: 20px; font-size: 0.8rem; font-weight: 500;
  transition: all 0.15s; white-space: nowrap;
}
.filter-chip:hover { border-color: var(--text-secondary); color: var(--text-primary); }
.filter-chip.active { background: var(--accent); border-color: var(--accent); color: var(--white); }
.toggle-filter {
  display: flex; align-items: center; gap: 6px;
  font-size: 0.8rem; color: var(--text-secondary); cursor: pointer;
}
.toggle-switch {
  position: relative; width: 36px; height: 20px;
  background: var(--bg-tertiary); border-radius: 10px;
  transition: background 0.2s;
}
.toggle-switch::after {
  content: ''; position: absolute; top: 2px; left: 2px;
  width: 16px; height: 16px; background: var(--text-secondary);
  border-radius: 50%; transition: all 0.2s;
}
.toggle-filter.active .toggle-switch { background: var(--accent); }
.toggle-filter.active .toggle-switch::after { left: 18px; background: var(--white); }

/* ===== IDEA GRID ===== */
.ideas-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 16px;
}
.idea-chart-placeholder {
  height: 140px; background: var(--bg-primary); border-radius: var(--radius-md);
  margin-bottom: 12px; overflow: hidden;
}
.idea-chart-placeholder canvas { width: 100%; height: 100%; }

/* ===== BROKER GRID ===== */
.broker-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 16px;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .chart-workspace {
    grid-template-columns: 1fr;
  }
  .watchlist-sidebar { display: none; }
  .hero h1 { font-size: 2rem; }
  .movers-grid { grid-template-columns: 1fr; }
  .detail-body { grid-template-columns: 1fr; }
  .detail-financials { border-top: 1px solid var(--border); border-left: none; }
}
@media (max-width: 768px) {
  html { font-size: 13px; }
  .navbar { padding: 0 12px; }
  .nav-links { display: none; }
  .section { padding: 20px 12px; }
  .hero { padding: 48px 16px 36px; }
  .hero h1 { font-size: 1.75rem; }
  .hero-actions { flex-direction: column; align-items: center; }
  .market-summary { padding: 0 12px; }
  .stats-banner { flex-direction: column; gap: 24px; }
  .ideas-grid, .broker-grid, .card-grid {
    grid-template-columns: 1fr;
  }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ===== ANIMATIONS ===== */
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.fade-in { animation: fadeIn 0.3s ease forwards; }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }
.pulse { animation: pulse 2s ease-in-out infinite; }

